<template><section v-if="entry" class="docker-tooling"><header><div><small>镜像自带 CLI 证据</small><h2 id="docker-tools">{{entry.name}} Docker 工具</h2></div><b>{{label}}</b></header><p v-if="entry.note">{{entry.note}}</p><div class="facts"><div><span>镜像锁</span><strong>{{entry.images.map(image=>`${image.role}: ${image.digestKey} (${image.tag})`).join(' · ')}}</strong></div><div><span>工具目录</span><strong>{{entry.toolRoots.join(' · ')}}</strong></div><div><span>关键工具</span><strong>{{entry.keyTools.join(' · ')}}</strong></div><div><span>操作闭环</span><code>{{entry.buildCommand}}；{{entry.runCommand}}</code></div></div><details v-for="x in evidence" :key="x.kind" v-show="x.text"><summary>{{x.label}}</summary><pre>{{x.text}}</pre></details></section></template>
<script setup lang="ts">import{computed}from'vue';import{dockerCatalogById}from'../data/dockerCatalog';import{dockerEvidence}from'../data/dockerEvidence';const p=defineProps<{product:string}>();const entry=computed(()=>dockerCatalogById[p.product]);const evidence=computed(()=>[{kind:'inventory',label:'完整工具清单',text:dockerEvidence(p.product,'inventory')},{kind:'session',label:'核心操作会话',text:dockerEvidence(p.product,'session')},{kind:'assert',label:'断言结果',text:dockerEvidence(p.product,'assert')}]);const label=computed(()=>({verified:'已验证',partial:'部分验证',documented:'待采集',unsupported:'不适用'}[entry.value?.status||'documented']))</script>
<style scoped>.docker-tooling{margin:2rem 0;padding:1rem;border:1px solid var(--vp-c-divider);border-radius:14px;background:var(--vp-c-bg-soft)}header{display:flex;justify-content:space-between;gap:1rem}h2{margin:.2rem 0;border:0}small{color:var(--vp-c-brand-1);font-weight:800}.facts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.6rem}.facts>div{display:grid;gap:.25rem;padding:.65rem;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg)}span{color:var(--vp-c-text-2)}strong,code{overflow-wrap:anywhere}pre{max-height:28rem;overflow:auto}@media(max-width:700px){.facts{grid-template-columns:1fr}}</style>
